import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.CezGkULV.js";var i=JSON.parse(`{"title":"Proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/README.md","filePath":"proposals/README.md"}`),a={name:`proposals/README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="proposals" tabindex="-1">Proposals <a class="header-anchor" href="#proposals" aria-label="Permalink to “Proposals”">​</a></h1><p>This directory holds the durable design record for one change per file.</p><p>Name each file <code>&lt;NNNN&gt;-&lt;slug&gt;.md</code>, using the next four-digit number and a kebab-case slug. Required frontmatter is <code>id: proposal.&lt;NNNN&gt;</code>, <code>title</code>, <code>authors</code> as a non-empty list, <code>status</code>, <code>pull-request</code>, and <code>supersedes</code>. Optional <code>issues</code> is a list of issue references or URLs. The normal lifecycle is <code>draft</code> → <code>awaiting-implementation</code> → <code>active-review</code> → <code>accepted</code> → <code>implemented</code>.</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th><th>Decided by</th><th>Phase</th></tr></thead><tbody><tr><td><code>draft</code></td><td>Being written and iterated on in the draft pull request. May carry <code>[NEEDS CLARIFICATION:</code>.</td><td>agent</td><td>2</td></tr><tr><td><code>awaiting-implementation</code></td><td>The approval owner settled the proposal. Implementation is underway or not yet started.</td><td>approval owner</td><td>3</td></tr><tr><td><code>active-review</code></td><td>First full pass at tests, guides and code exists; report posted and pull request marked ready.</td><td>agent</td><td>4</td></tr><tr><td><code>returned-for-revisions</code></td><td>The acceptance review asked for changes. Back to implementation, or to the proposal if the design changed.</td><td>approval owner</td><td>4 → 3 or 2</td></tr><tr><td><code>accepted</code></td><td>The approval owner accepted the work. The vision update and final implementation record are underway.</td><td>approval owner</td><td>5</td></tr><tr><td><code>implemented</code></td><td>The accepted implementation and final records are committed in the feature pull request before merge. Merge and required delivery remain separate.</td><td>agent</td><td>5</td></tr><tr><td><code>rejected</code></td><td>The approval owner declined the change. Kept as record.</td><td>approval owner</td><td>terminal</td></tr><tr><td><code>withdrawn</code></td><td>The author pulled it. Kept as record.</td><td>either</td><td>terminal</td></tr><tr><td><code>superseded</code></td><td>A later proposal replaced it.</td><td>either</td><td>terminal</td></tr></tbody></table><p><strong>Decided by</strong> names the approval owner: the human, or the strategist for decisions delegated by <a href="https://github.com/markmals/bento/blob/main/AGENTS.md#bounded-build-mandates" target="_blank" rel="noreferrer">an active build mandate</a>. Proposal approval requires settled intent and recorded authority. Acceptance of implementation additionally requires the readiness report, fresh checks, independent reviews, and an exercised preview. An implementer&#39;s completion claim alone cannot authorize acceptance.</p><p>Every proposal records where its authority came from in <code>## Authorization</code>: the human&#39;s direct consent for this change, or the mandate proposal and approved revision it runs under, why the change fits inside it, and the approval decisions the strategist took. A proposal may also carry an optional <code>## Build mandate</code> section; once the human approves that proposal, it is what delegates a bounded set of decisions. Mandates need no separate directory, frontmatter key, or status — an ordinary proposal in this lifecycle carries them — and a mandate proposal cannot authorize itself.</p><p><code>implemented</code> records the accepted implementation in the original feature pull request after the vision update and before merge. It does not claim that the pull request merged or that required delivery happened. The pull request records integration; keep any required release visible in the proposal or pull request until separately authorized and performed. A merge-only change needs no release. For already merged pull requests, inspect the merged revision before deciding whether a local <code>accepted</code> record needs reconciliation; do not create a status-only follow-up pull request.</p><p>A proposal stays <code>draft</code> for as long as it takes. It is published to the draft pull request as soon as there is something to react to, and the approval owner iterates on it there — editing directly, or asking for changes — until the design is settled. Iteration is the normal case, not a sign of a bad first draft.</p><p>History is preserved: never delete a superseded entry — mark it <code>superseded</code> and link its replacement through <code>supersedes</code>.</p>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};